style.css:
@-moz-document domain("roblox.com"), domain("www.roblox.com"), domain("create.roblox.com"), domain("economy.roblox.com"), domain("catalog.roblox.com"), domain("develop.roblox.com") {
/* ===== CUSTOM BACKGROUND IMAGE ===== */
    body {
        background: url(https://www.vice.com/wp-content/uploads/sites/2/2021/02/1611779956370-screen-shot-2021-01-27-at-33858-pm.png) no-repeat center center fixed !important;
        background-size: cover !important;
    }

    /* ===== DARK OVERLAY TO IMPROVE VISIBILITY ===== */
    body::before {
        content: "";
        position: fixed;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        background: rgba(0, 0, 0, 0.5); /* Adjust for better visibility */
        z-index: -1;
    }

    /* ===== MAKE UI ELEMENTS STAND OUT ===== */
    .navbar, /* Top Navbar */
    .game-card, /* Game Thumbnails */
    .game-details, /* Game Info */
    .container-main, /* Main Page Containers */
    .content, /* General Content */
    .chat-container, /* Chat Window */
    .profile-container, /* Profile Page */
    .inventory-container, /* Inventory Page */
    .catalog-container, /* Catalog Page */
    .develop-container, /* Develop Page */
    .avatar-container { /* Avatar Page */
        background: rgba(0, 0, 0, 0.7) !important;
        border-radius: 10px !important;
        padding: 10px !important;
    }

    /* ===== RGB COLOR CHANGING UI HIGHLIGHT ===== */
    @keyframes rgbGlow {
        0% { box-shadow: 0 0 10px red; }
        25% { box-shadow: 0 0 10px blue; }
        50% { box-shadow: 0 0 10px green; }
        75% { box-shadow: 0 0 10px purple; }
        100% { box-shadow: 0 0 10px red; }
    }

    .navbar, 
    .game-card, 
    .game-details, 
    .container-main, 
    .content, 
    .chat-container, 
    .profile-container, 
    .inventory-container, 
    .catalog-container, 
    .develop-container, 
    .avatar-container {
        animation: rgbGlow 3s infinite alternate !important;
    }

    /* ===== TEXT COLOR FIX (ENSURES READABILITY) ===== */
    * {
        color: white !important;
        text-shadow: 0px 0px 5px rgba(0, 0, 0, 0.7) !important;
    }

    /* ===== SCROLLBAR CUSTOMIZATION ===== */
    ::-webkit-scrollbar {
        width: 8px !important;
    }

    ::-webkit-scrollbar-thumb {
        background: linear-gradient(45deg, red, blue, green, purple) !important;
        border-radius: 4px !important;
    }

    ::-webkit-scrollbar-track {
        background: rgba(0, 0, 0, 0.2) !important;
    }
}
